const candidateSkin = process.env.MX_TEST_SKIN || 'style2';
const out = process.env.MX_OUTPUT_DIR || 'docs/styles/'+candidateSkin+'/implementation/round1';
const {chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1000,height:1100}});const rows=[],errors=[];p.on('pageerror',e=>errors.push(String(e)));async function open(skin,scene='figma',extra={}){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin,scene,width:440,height:782,...extra}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000})}
for(const action of ['fold','call','raise','quick','voice','lifecycle']){const pair=[];for(const skin of ['style1',candidateSkin]){await open(skin,action==='voice'?'media-voice':'figma');if(['fold','call'].includes(action))await p.locator('.mx-operation-'+action).click();if(action==='raise'){await p.locator('.mx-operation-raise').click();await p.locator('.mx-raise-range').press('ArrowUp');await p.locator('.mx-raise-confirm').click()}if(action==='quick'){await p.locator('.mx-quick-bet').first().click();if(await p.locator('.mx-raise-confirm').isVisible())await p.locator('.mx-raise-confirm').click()}
if(action==='voice')await p.locator('.mx-nav-button[data-action=voice]').click();if(action==='lifecycle'){await p.locator('#audit-controls button').getByText('离桌',{exact:true}).click();await p.locator('#audit-controls button').getByText('重新进入',{exact:true}).click();await p.locator('.mx-seat-mine').waitFor();await p.locator('#audit-controls button').getByText('切桌',{exact:true}).click();await p.locator('.mx-seat-mine').waitFor();await p.locator('.mx-operation-call').click()}
await p.waitForTimeout(80);pair.push(await p.evaluate(()=>({phase:document.querySelector('#audit-stage').dataset.phase,pot:document.querySelector('.mx-pot')?.textContent,stack:document.querySelector('.mx-seat-mine .mx-stack')?.textContent,success:[...document.querySelectorAll('#audit-log li')].filter(e=>e.textContent.startsWith('本地操作成功')).map(e=>e.textContent),voice:document.querySelector('.mx-nav-button[data-action=voice]')?.getAttribute('aria-pressed'),tables:document.querySelectorAll('.mx-table').length})));}
rows.push({action,pair,pass:JSON.stringify(pair[0])===JSON.stringify(pair[1])&&(action==='voice'||pair.every(r=>r.success.length===1&&r.tables===1))});}
fs.mkdirSync(out,{recursive:true});fs.writeFileSync(out+'/behavior.json',JSON.stringify({rows,errors},null,2));console.log(rows.map(r=>({action:r.action,pass:r.pass})));if(errors.length||rows.some(r=>!r.pass))process.exitCode=1;await b.close()})();
